```python
class Gradebook:
    def __init__(self) -> None:
        # Maps assignment name -> (weight, kind)
        self._assignments = {}
        # Maps student -> {assignment_name: grade}
        self._grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError(f"Invalid kind: {kind!r} (must be 'homework' or 'quiz')")
        self._assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment!r}")
        if grade < 2.0 or grade > 5.0:
            raise ValueError("Grade must be between 2.0 and 5.0")
        self._grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})

        # Determine the lowest quiz grade to drop (if more than one quiz)
        quiz_grades = {
            name: g
            for name, g in student_grades.items()
            if name in self._assignments and self._assignments[name][1] == "quiz"
        }
        dropped = None
        if len(quiz_grades) > 1:
            dropped = min(quiz_grades, key=lambda n: quiz_grades[n])

        total_weight = 0.0
        weighted_sum = 0.0
        for name, grade in student_grades.items():
            if name == dropped:
                continue
            weight, _kind = self._assignments[name]
            weighted_sum += weight * grade
            total_weight += weight

        if total_weight == 0:
            return 0.0

        return round(weighted_sum / total_weight, 2)
```

### Notes on behavior

- **Weighted average**: Computed as `sum(weight * grade) / sum(weight)` over the student's recorded assignments (excluding any dropped quiz).
- **Dropped quiz**: Only applied when a student has **more than one** quiz recorded. The lowest quiz grade is excluded from both the numerator and the weight total.
- **Validation**: `record` raises `ValueError` for grades outside `[2.0, 5.0]`, and `KeyError` for unknown assignments. `add_assignment` also validates `kind`.
- **Rounding**: `average()` returns the value rounded to two decimal places; returns `0.0` if the student has no qualifying grades.

